\begin{theorem}
For all $n \in \mathbb{N}$, $\sum_{i=1}^{n} i = \frac{n(n+1)}{2}$.
\end{theorem}

\begin{proof}
For $n = 1$ both sides equal $1$. Assume the claim for $n$. Then
\begin{align}
  \sum_{i=1}^{n+1} i &= \frac{n(n+1)}{2} + (n+1) \\
                     &= \frac{(n+1)(n+2)}{2},
\end{align}
completing the induction.
\end{proof}
